#!/usr/bin/env node
// website/app/page.tsx:13 links the marketing sample frame at
// `${BASE_PATH}/samples/kestrel/report.html`, which Next only serves if that
// file exists under website/public/ at build time. examples/kestrel/report.html
// is the committed source of truth (generated by `saylent report`, see
// examples/kestrel/README.md); this script copies it into website/public/
// before every `site:build` so the two can never drift. The copy itself is
// NOT committed — website/public/samples/ is gitignored — so this step must
// run before every build, local or CI (wired into `npm run site:build` and
// therefore .github/workflows/pages.yml, which already calls it).
//
// Usage: node scripts/copy-kestrel-sample.mjs
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const srcHtml = path.join(repoRoot, "examples/kestrel/report.html");
const destDir = path.join(repoRoot, "website/public/samples/kestrel");
const destHtml = path.join(destDir, "report.html");

if (!existsSync(srcHtml)) {
  console.error(
    `Missing ${path.relative(repoRoot, srcHtml)} — generate it first:\n` +
      `  npm run build:cli\n` +
      `  node packages/cli/dist/saylent.js report examples/kestrel/run.json --out examples/kestrel\n`,
  );
  process.exit(1);
}

// the ONE page a tweet links to had no description, no share card
// and `<meta name="robots" content="noindex">`, so it previewed as a bare URL
// and could not be found. That default is right for every report the CLI
// writes for a user (their data, their machine) and wrong for this one
// published sample - so the fix lives HERE, in the copy step, and the renderer
// is left alone. Everything below operates on whatever report.html currently
// is; it never assumes a particular head layout.
const SITE_URL = "https://yotambraun.github.io/saylent";
const SHARE_CARD = `${SITE_URL}/media/share-card-1200x630.png`;
const SAMPLE_URL = `${SITE_URL}/samples/kestrel/report.html`;
const TITLE = "Saylent sample report: what AI assistants say about Kestrel Uptime";
const DESCRIPTION =
  "A real Saylent audit of Kestrel Uptime, a fictional company we audit: what ChatGPT, Claude, Gemini and Perplexity answered, the pages they cited, which AI bots the site lets in, and the drafted fixes.";

const esc = (s) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");

const META = [
  `<meta name="description" content="${esc(DESCRIPTION)}">`,
  `<meta property="og:type" content="article">`,
  `<meta property="og:site_name" content="Saylent">`,
  `<meta property="og:url" content="${SAMPLE_URL}">`,
  `<meta property="og:title" content="${esc(TITLE)}">`,
  `<meta property="og:description" content="${esc(DESCRIPTION)}">`,
  `<meta property="og:image" content="${SHARE_CARD}">`,
  `<meta name="twitter:card" content="summary_large_image">`,
  `<meta name="twitter:title" content="${esc(TITLE)}">`,
  `<meta name="twitter:description" content="${esc(DESCRIPTION)}">`,
  `<meta name="twitter:image" content="${SHARE_CARD}">`,
].join("\n");

/** Strip the renderer's `noindex` (correct for a private report, wrong for the
 *  published sample) and inject the social/description block, whatever else the
 *  head happens to contain. */
function publishHead(html) {
  let out = html.replace(/[ \t]*<meta\s+name=["']robots["'][^>]*>\s*\n?/gi, "");
  // Insert straight after <head...>, so nothing already in the head is moved.
  const head = /<head[^>]*>/i.exec(out);
  if (!head) {
    console.warn("no <head> found in the sample report - social meta not injected");
    return out;
  }
  const at = head.index + head[0].length;
  return `${out.slice(0, at)}\n${META}${out.slice(at)}`;
}

mkdirSync(destDir, { recursive: true });
writeFileSync(destHtml, publishHead(readFileSync(srcHtml, "utf8")), "utf8");
console.log(
  `copied ${path.relative(repoRoot, srcHtml)} -> ${path.relative(repoRoot, destHtml)} (+ social meta, noindex removed)`,
);
